import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "हल्की सी ठोकर से हड्डी टूट गई? कद पहले से छोटा लगने लगा? कहीं हड्डियां अंदर से कमज़ोर तो नहीं हो रहीं? इसकी जांच है डेक्सा स्कैन. आखिर तक देखिए.",
 "डेक्सा यानी ड्युअल एनर्जी एक्स रे एब्ज़ॉर्पशियोमेट्री. इसमें दो तरह की बहुत हल्की एक्स रे किरणों से, हड्डियों का घनत्व, यानी बोन मिनरल डेंसिटी, मापा जाता है. आमतौर पर कमर की रीढ़, और कूल्हे की हड्डी देखी जाती है.",
 "ऑस्टियोपोरोसिस में हड्डियां अंदर से पतली और कमज़ोर हो जाती हैं, और आसानी से टूट सकती हैं. यह चुपचाप बढ़ती है. अक्सर पहला लक्षण ही हड्डी का टूटना होता है. भारत में यह एक बड़ी स्वास्थ्य समस्या है.",
 "यह जांच किसे करवानी चाहिए? मेनोपॉज़ के बाद की महिलाएं, और बुज़ुर्ग पुरुष. जिनकी हड्डी हल्की चोट से टूटी हो. जिनका कद डेढ़ इंच या ज़्यादा घटा हो. लंबे समय से स्टेरॉयड लेने वाले. और धूम्रपान करने वाले. जांच का फैसला डॉक्टर करते हैं.",
 "क्या यह सुरक्षित है? हां. इसकी रेडिएशन, छाती के एक सामान्य एक्स रे के दसवें हिस्से से भी कम होती है. यह दर्द रहित है, और आमतौर पर दस से तीस मिनट लगते हैं. आप बस मेज़ पर लेटते हैं, और मशीन ऊपर से गुज़रती है. प्रेगनेंसी हो, तो पहले बताएं.",
 "तैयारी कैसे करें? खाना सामान्य खाएं, पर कम से कम चौबीस घंटे पहले कैल्शियम की गोली न लें. बिना धातु के ढीले कपड़े पहनें, गहने उतार दें. हाल में बेरियम जांच, या सी टी में कंट्रास्ट इंजेक्शन लगा हो, तो पहले बताएं. कुछ दिन रुकना पड़ सकता है.",
 "रिपोर्ट में सबसे ज़रूरी है टी स्कोर, जो आपकी हड्डी की तुलना एक स्वस्थ युवा व्यक्ति से करता है. माइनस एक या उससे ऊपर, सामान्य. माइनस एक से माइनस ढाई के बीच, ऑस्टियोपीनिया, यानी हड्डी थोड़ी कमज़ोर. और माइनस ढाई या उससे नीचे, ऑस्टियोपोरोसिस.",
 "ज़ेड स्कोर आपकी तुलना, आपकी ही उम्र के लोगों से करता है. यह खासकर बच्चों, युवाओं, और मेनोपॉज़ से पहले की महिलाओं में देखा जाता है. बहुत कम ज़ेड स्कोर हो, तो डॉक्टर कारण ढूंढने के लिए और जांच करवा सकते हैं.",
 "कुछ ज़रूरी बातें. अगली जांच उसी सेंटर, और उसी मशीन पर करवाएं, ताकि तुलना सही हो. रीढ़ में गठिया या पुरानी सर्जरी से, रिपोर्ट पर असर पड़ सकता है. और इलाज का फैसला, सिर्फ डॉक्टर करते हैं.",
 close_voice("क्या आपने या आपके माता पिता ने कभी डेक्सा स्कैन करवाया है?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/dexar_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/dexa_{i}.wav"],check=True); f=f"/tmp/dexa_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/dexa_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
